// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint128 a1, uint128 a2, address actor, uint256 ts) public {
        vm.assume(a1 <= VALUE_CAP);
        vm.assume(a2 <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && a1 > 0 && a2 > 0);
        vm.deal(actor, uint256(a1) + uint256(a2));
        vm.warp(ts);

        vm.prank(actor);
        c.Put{value: a1}(0);
        vm.prank(actor);
        c.Put{value: a2}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == uint256(a1) + uint256(a2));
    }
}
